def fit(a, y):
    keep = np.ones(len(a), bool)
    for _ in range(15):
        b = np.linalg.lstsq(a[keep], y[keep], rcond=None)[0]
        d = np.linalg.norm(a @ b - y, axis=1)
        nxt = d <= max(6 * np.median(d), 0.00075)
        if nxt.sum() < a.shape[1] or np.array_equal(nxt, keep):
            break
        keep = nxt
    return (b, keep)

def _stress_map(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack([np.ones(len(raw)), raw]), cal['true_channel_loads'], rcond=None)[0].sum(axis=1)
